import { getIds, getLabels, getMappedField, getTitle } from '../listInstance';

describe('listInstance', () => {
  describe('getIds', () => {
    test('returns ids', () => {
      const arr = [
        {
          id: 1,
          test: 'test',
        },
      ];
      expect(getIds(arr)).toEqual([1]);
    });
  });

  describe('getLabels', () => {
    test('returns labels', () => {
      const arr = [
        {
          id: 1,
          test: 'test',
          label: 'label1',
        },
        {
          id: 2,
          test: 'test',
          label: 'label2',
        },
      ];
      expect(getLabels(arr)).toEqual(['label1', 'label2']);
    });
  });

  describe('getMappedField', () => {
    test('should default', () => {
      expect(getMappedField()).toEqual([]);
      expect(getMappedField({})).toEqual([]);
      expect(getMappedField([])).toEqual([]);
    });

    test('should return specified field', () => {
      expect(
        getMappedField(
          [
            { name: 'tim', extra: 'pepperoni' },
            { name: 'arthur', extra: 'suasage' },
            { name: 'bedivere', extra: 'bacon' },
          ],
          'name',
        ),
      ).toEqual(['tim', 'arthur', 'bedivere']);
      expect(
        getMappedField(
          [
            { team: 'the u', mascot: 'swoop' },
            { team: 'davis', mascot: 'dartman' },
            { team: 'weber', mascot: 'waldo' },
          ],
          'mascot',
        ),
      ).toEqual(['swoop', 'dartman', 'waldo']);
    });
  });

  describe('getTitle', () => {
    it('should return when no instanceTitle', () => {
      expect(getTitle('listTemplateTitle', null)).toEqual('listTemplateTitle');
    });

    it('should concat when there is an instanceTitle', () => {
      expect(getTitle('listTemplateTitle', 'listInstanceTitle')).toEqual(
        'listInstanceTitle (listTemplateTitle)',
      );
    });

    it('should concat when there is an instanceTitle', () => {
      expect(getTitle(null, null)).toEqual('[Template Deleted]');
    });
  });
});
